function validate([intervals]) {
  if (intervals.length < 1 || intervals.length > 100000) return 'intervals needs 1 to 100000 entries.';
  for (const pair of intervals) {
    if (!Array.isArray(pair) || pair.length !== 2) return 'Each interval is a pair [left, right].';
    const [left, right] = pair;
    if (!Number.isInteger(left) || !Number.isInteger(right)) return 'Interval ends are integers.';
    if (left < 1 || right > 1000000 || left > right) return 'Each interval needs 1 <= left <= right <= 10^6.';
  }
  return null;
}

