function minGroups(intervals) {
  const events = [];
  for (const [start, end] of intervals) {
    events.push([start, 1]);
    events.push([end + 1, -1]);
  }
  events.sort((a, b) => a[0] - b[0] || a[1] - b[1]);

  let active = 0;
  let best = 0;
  for (const [point, change] of events) {
    active += change;
    best = Math.max(best, active);
  }
  return best;
}

