function minGroups(intervals) {
  const n = intervals.length;
  const clash = (a, b) => Math.max(a[0], b[0]) <= Math.min(a[1], b[1]);
  const group = new Array(n).fill(-1);
  const place = (i, k, used) => {
    if (i === n) return true;
    for (let g = 0; g < Math.min(k, used + 1); g++) {
      let ok = true;
      for (let j = 0; j < i; j++) if (group[j] === g && clash(intervals[i], intervals[j])) { ok = false; break; }
      if (!ok) continue;
      group[i] = g;
      if (place(i + 1, k, Math.max(used, g + 1))) return true;
      group[i] = -1;
    }
    return false;
  };
  for (let k = 1; ; k++) if (place(0, k, 0)) return k;
}

