function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const top = rand() < 0.5 ? 1000000 : 5000;
    const span = rand() < 0.5 ? 50 : Math.floor(top / 4);
    return [Array.from({ length: 2000 }, () => {
      const left = int(1, top);
      return [left, Math.min(1000000, left + int(0, span))];
    })];
  }
  const n = int(1, 8);
  const top = rand() < 0.4 ? 6 : 15;
  return [Array.from({ length: n }, () => {
    const left = int(1, top);
    return [left, Math.min(top, left + int(0, 5))];
  })];
}
